function dataUrlToImageContent(dataUrl: string): ImageContent | null {
  const match = dataUrl.match(/^data:([^;,]+);base64,(.*)$/);
  if (!match) return null;
  return { type: "image", mimeType: match[1], data: match[2] };
}

