	return speechSetting.load();
}

export function saveWebSpeechSettings(settings: WebSpeechSettings): void {
	speechSetting.save(settings);
}

export function subscribeWebSpeechSettings(callback: (settings: WebSpeechSettings) => void): () => void {
	return speechSetting.subscribe(callback);
}

export type SpeechCredentialProvider = "openai" | "google";

export interface SpeechCredential {
	provider: SpeechCredentialProvider;
	apiKey: string;
}

/**
 * Pick the credential used for speech input (STT / realtime). Prefers a genuine
 * OpenAI key, then Google/Gemini. The OpenAI check uses the "openai" provider
 * only — that is the real api.openai.com. A custom-base OpenAI-compatible
 * provider is stored under its own name and is intentionally NOT treated as an
 * OpenAI speech credential, since the transcription/realtime endpoints are
 * OpenAI-specific.
 */
export async function resolveSpeechCredential(
	getApiKey: (provider: string) => Promise<string | undefined>,
): Promise<SpeechCredential | null> {
	const openai = await getApiKey("openai");
	if (openai) return { provider: "openai", apiKey: openai };
	const google = await getApiKey("google");
	if (google) return { provider: "google", apiKey: google };
	return null;
}

const DUPLEX_PROVIDER_IDS = new Set<SpeechProviderId>(["gemini-live", "openai-realtime"]);

export function isDuplexSpeechProvider(id: SpeechProviderId): boolean {
	return DUPLEX_PROVIDER_IDS.has(id);
}

/**
 * Decide whether the prompt mic button should open a live bidirectional session
 * or do one-shot speech-to-text. Duplex only when speech is enabled and the
 * active provider is a duplex provider (OpenAI Realtime / Gemini Live).
 */
export function speechInputMode(settings: WebSpeechSettings): "duplex" | "stt" {
	return settings.enabled && settings.microphoneEnabled && isDuplexSpeechProvider(settings.providerId) ? "duplex" : "stt";
}

/** Which LLM provider backs a speech provider, for capability lookup. */
export function speechProviderModel(settings: WebSpeechSettings): ProviderModelDescriptor | null {
	if (settings.providerId === "openai-realtime") return { provider: "openai", id: settings.model, api: "openai-realtime" };
	if (settings.providerId === "gemini-live") return { provider: "google", id: settings.model, api: "google-live" };
	return null;
}

/**
 * The realtime tier the current speech settings can actually be driven at.
 * Non-duplex providers (plain TTS, custom endpoints) are tier 0 by definition.
 */
export function resolveSpeechRealtimeTier(settings: WebSpeechSettings): RealtimeTierDescriptor {
	const model = speechProviderModel(settings);
	if (!model) {
		return {
			tier: 0,
			label: "Half duplex (push to talk)",
			video: false,
			videoRoute: "none",
			capReason: "This provider only synthesizes speech; it cannot hold a live session.",
		};
	}
	return resolveRealtimeTier(model);
}

let audioContext: AudioContext | null = null;
let scheduledUntil = 0;
/** Sources queued but not yet finished, so barge-in can cut them off. */
const scheduledSources = new Set<AudioBufferSourceNode>();

export function getAudioContext(): AudioContext | null {
	if (typeof window === "undefined") return null;
	const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
	if (!AudioContextCtor) return null;
	audioContext ??= new AudioContextCtor();
	return audioContext;
}

export async function primeSpeechAudio(): Promise<void> {
	const context = getAudioContext();
	if (context && context.state === "suspended") await context.resume();
}

function decodeBase64Pcm(base64: string): Int16Array {
	const binary = window.atob(base64);
	const bytes = new Uint8Array(binary.length);
	for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
	return new Int16Array(bytes.buffer);
}

export function schedulePcmAudio(base64: string, sampleRate = RECEIVE_SAMPLE_RATE): boolean {
	const context = getAudioContext();
	if (!context) return false;

	const pcm = decodeBase64Pcm(base64);
	if (pcm.length === 0) return false;

	const buffer = context.createBuffer(1, pcm.length, sampleRate);
	const channel = buffer.getChannelData(0);
	for (let i = 0; i < pcm.length; i += 1) channel[i] = pcm[i] / 32768;

	const source = context.createBufferSource();
	source.buffer = buffer;
	source.connect(context.destination);
	const startAt = Math.max(context.currentTime + 0.03, scheduledUntil);
	source.start(startAt);
	scheduledUntil = startAt + buffer.duration;
	trackScheduledSource(source);
	return true;
}

function trackScheduledSource(source: AudioBufferSourceNode): void {
	scheduledSources.add(source);
	source.addEventListener("ended", () => scheduledSources.delete(source), { once: true });
}

/**
 * Cut off audio that has been queued but not yet played.
 *
 * Providers that stream PCM (rather than delivering a WebRTC track) can have
 * seconds of assistant speech buffered ahead of the speaker. Without this, a
 * learner interrupting would keep hearing the sentence they just cut off.
 */
export function stopScheduledAudio(): void {
	for (const source of scheduledSources) {
		try {
			source.stop();
		} catch {
			// Already stopped or never started; either way it is not audible.
		}
	}
	scheduledSources.clear();
	const context = getAudioContext();
	scheduledUntil = context ? context.currentTime : 0;
}

export async function scheduleAudioBlob(blob: Blob): Promise<boolean> {
	const context = getAudioContext();
	if (!context) return false;
	const arrayBuffer = await blob.arrayBuffer();
	const audioBuffer = await context.decodeAudioData(arrayBuffer.slice(0));
	const source = context.createBufferSource();
	source.buffer = audioBuffer;
	source.connect(context.destination);
	const startAt = Math.max(context.currentTime + 0.03, scheduledUntil);
	source.start(startAt);
	scheduledUntil = startAt + audioBuffer.duration;
	trackScheduledSource(source);
	return true;
}

export function speechErrorMessage(error: unknown, fallback: string): string {
	if (error instanceof Error && error.message.trim()) return error.message.trim();
	if (typeof error === "string" && error.trim()) return error.trim();
	return fallback;
}

