    47	export function prepareMessagesForRetry(messages: AgentMessage[]): AgentMessage[] | null {
    48		if (!isRetryableAssistantMessage(messages.at(-1))) return null;
    49		const remaining = messages.slice(0, -1).map(cloneMessage);
    50		const hasUserTurn = remaining.some((message) => {
    51			const role = (message as { role?: unknown }).role;
    52			return role === "user" || role === "user-with-attachments";
    53		});
    54		return hasUserTurn ? remaining : null;
    55	}
